    /// <summary>
    /// 表达式类型枚举
    /// </summary>
    public enum ExprType
    {
        // 基本整数类型
        Char,
        Short,
        Int,
        Long,
        LongLong,       // long long (64-bit)

        // 无符号整数类型
        UnsignedChar,
        UnsignedShort,
        UnsignedInt,
        UnsignedLong,
        UnsignedLongLong, // unsigned long long (64-bit)

        // 浮点类型
        Float,
        Double,

        // 指针类型
        CharPtr,
        ShortPtr,
        IntPtr,
        LongPtr,
        FloatPtr,
        DoublePtr,
        VoidPtr,

        // C99 布尔类型
        Bool,  // _Bool / bool (1 byte)

        // 特殊类型
        Void,
        Unknown,
        Struct  // struct/union types — use GetTypeSizeFromString for actual size
    }

    /// <summary>
    /// C 语言代码生成器，将 AST 转换为 VML 汇编
    /// </summary>
    public partial class CodeGenerator : CLikeCodegen<CodeGenerator>
    {
        // ====== 标签隔离 ======

        /// <summary>基于文件名初始化标签计数器偏移，防止 include 时标签冲突</summary>
        public void InitLabelCounter(string fileName)
        {
            int hash = 0;
            foreach (char c in fileName) hash = hash * 31 + c;
            labelCounter = Math.Abs(hash) % 10000 * 10000;
        }

        // ====== CLikeCodegen 抽象方法实现 ======
        protected override int GetTypeSizeByEnum(int typeEnum) => (ExprType)typeEnum switch
        {
            ExprType.Char or ExprType.UnsignedChar or ExprType.Bool => 1,
            ExprType.Short or ExprType.UnsignedShort => 2,
            ExprType.Int or ExprType.UnsignedInt or ExprType.Float => 4,
            ExprType.Long or ExprType.UnsignedLong or ExprType.LongLong or ExprType.UnsignedLongLong or ExprType.Double => 8,
            _ when typeEnum >= (int)ExprType.CharPtr && typeEnum <= (int)ExprType.VoidPtr => 4,
            _ => 4
        };
        protected override bool IsFloatType(int typeEnum) => (ExprType)typeEnum is ExprType.Float;
        protected override bool IsDoubleType(int typeEnum) => (ExprType)typeEnum is ExprType.Double;
        protected override bool IsLongType(int typeEnum) => (ExprType)typeEnum is ExprType.Long or ExprType.UnsignedLong or ExprType.LongLong or ExprType.UnsignedLongLong;
        protected override int GetDefaultType() => (int)ExprType.Int;

        /// <summary>获取指针步长: sizeof(*ptr)</summary>
        private int GetPointerStepSize(ExprType ptrType)
        {
            var pointed = ptrType switch
            {
                ExprType.CharPtr => ExprType.Char,
                ExprType.ShortPtr => ExprType.Short,
                ExprType.IntPtr => ExprType.Int,
                ExprType.LongPtr => ExprType.Long,
                ExprType.FloatPtr => ExprType.Float,
                ExprType.DoublePtr => ExprType.Double,
                ExprType.VoidPtr => ExprType.Char,
                _ => ExprType.Int
            };
            return GetTypeSizeByEnum((int)pointed);
        }

        /// <summary>根据变量名获取指针步长（支持 struct 指针）</summary>
        private int GetPointerStepSizeForVar(string varName)
        {
            if (!variableTypes.TryGetValue(varName, out var vt))
                return 1;
            if (!IsPointerType(vt))
                return 1;
            // 如果是 struct 指针，从 struct 定义获取实际大小
            if (vt == ExprType.IntPtr && variableStructTypes.TryGetValue(varName, out var stName))
            {
                int structSize = GetTypeSizeFromString(stName);
                if (structSize > 0) return structSize;
            }
            return GetPointerStepSize(vt);
        }
        // ====== ======

        private Program                                          ast;
        private int                                              stackFrameSize;
        private Dictionary<string, int>                          variables;
        private HashSet<string>                                  vlaVariables = new();  // VLA变量名集合
        private Dictionary<string, string>                       staticLocals; // static局部变量: varName → dataSection label
        private Dictionary<string, ExprType>                     variableTypes;
        private Dictionary<string, string>                       variableStructTypes;
        private Dictionary<string, string>                       variableTypeStrings; // 变量名 → 原始类型字符串(用于提取数组维度)
        private Dictionary<string, int>                          enumValues;
        private Dictionary<string, string>                       typeAliases;
        private Dictionary<string, string>                       functionEndLabels;
        private Function                                         CurrentFunction;
        private Dictionary<string, StructDecl>                   structs;
        private Dictionary<string, UnionDecl>                    unions;
        private int                                              hiddenReturnPtrOffset; // offset from R12 for hidden struct return pointer (-1 if none)
        private HashSet<string>                                  arrayLocalVars; // 局部数组变量名 → 用于数组到指针退化
        private HashSet<string>                                  globalArrayVars; // 全局数组变量名 → 用于数组到指针退化
        private Dictionary<string, List<int?>>                   localArrayDimensions; // 局部数组变量名 → 维度列表

        /// <summary>
        /// 初始化代码生成器
        /// </summary>
        /// <param name="ast">抽象语法树</param>
        public CodeGenerator(Program ast) : base()
        {
            this.ast          = ast;
            variableTypes     = new Dictionary<string, ExprType>();
            variableStructTypes = new Dictionary<string, string>();
            variableTypeStrings = new Dictionary<string, string>();
            functionEndLabels = new Dictionary<string, string>();
            // 收集所有枚举常量到 enumValues 字典
            enumValues = new Dictionary<string, int>();
            if (ast.EnumConstants != null)
            {
                foreach (var enumEntry in ast.EnumConstants)
                {
                    foreach (var member in enumEntry.Value)
                    {
                        enumValues[member.Key] = member.Value;
                    }
                }
            }
            // 初始化类型别名字典
            typeAliases = new Dictionary<string, string>();

            // 初始化struct/union字典
            structs = ast.Structs;
            unions = ast.Unions;

            // 初始化数组变量跟踪
            arrayLocalVars = new HashSet<string>();
            globalArrayVars = new HashSet<string>();
            localArrayDimensions = new Dictionary<string, List<int?>>();
            foreach (var varDecl in ast.Variables)
            {
                if (varDecl.IsArray)
                    globalArrayVars.Add(varDecl.Name);
            }

            // 处理类型定义
            if (ast.TypeDefs != null)
            {
                foreach (var typedef in ast.TypeDefs)
                {
                    // 将类型别名映射到原始类型
                    typeAliases[typedef.Key.ToLower()] = typedef.Value;
                }
            }

            InitSimpleCompiler(threeOperandInt: false);
        }

        /// <summary>
        /// 解析类型名称，处理类型别名
        /// </summary>
        private string ResolveTypeName(string typeName)
        {
            // 解析 typedef 链，如 "state_t" → "uint8_t[4][4]" → "unsigned char[4][4]"
            if (string.IsNullOrEmpty(typeName)) return typeName;
            string current = typeName;
            int maxDepth = 20;
            while (maxDepth-- > 0 && typeAliases.TryGetValue(current, out var resolved))
            {
                // struct/union markers are terminal
                if (resolved == "struct" || resolved == "union") break;
                current = resolved;
            }
            return current;
        }

        /// <summary>
        /// 解析 struct/union 类型名称（包括 typedef 别名）。
        /// 返回 struct/union 的完整类型字符串，或 null。
        /// </summary>
        private string ResolveStructType(string typeName)
        {
            if (string.IsNullOrEmpty(typeName)) return null;
            string lower = typeName.ToLower().Trim();
            // Strip trailing pointer stars
            lower = lower.TrimEnd('*', ' ');
            // Direct struct/union prefix
            if (lower.StartsWith("struct ") || lower.StartsWith("union "))
                return lower;
            // Try typedef alias → struct/union
            if (typeAliases.TryGetValue(lower, out var resolved))
            {
                if (resolved == "struct" || resolved == "union")
                    return resolved + " " + lower;
                if (resolved.StartsWith("struct ") || resolved.StartsWith("union "))
                    return resolved.ToLower();
            }
            // Also try original case with ast.TypeDefs
            if (ast.TypeDefs.TryGetValue(lower, out var resolved2))
            {
                if (resolved2 == "struct" || resolved2 == "union")
                    return resolved2 + " " + lower;
                if (resolved2.StartsWith("struct ") || resolved2.StartsWith("union "))
                    return resolved2.ToLower();
            }
            return null;
        }
    }
